// Base paths served by the Mintlify-hosted (API/cloud) static-export renderer.
// Each entry corresponds to one build target in
// packages/static-export-lambda/Dockerfile (runtime-default / runtime-bp2 /
// runtime-bp3) and one variant in the infra repo's STATIC_EXPORT_VARIANTS
// (mintlify-aws/infrastructure → packages/deploy/constants/staticExport.ts).
// Keep these three lists in sync when adding a base path.
//
// Named API_STATIC_EXPORT to distinguish the cloud-hosted set from the
// self-hosted Dockerfile.selfhost variants (which additionally serve
// '/docs/demo' and are not hosted by us).
export const API_STATIC_EXPORT_BASE_PATHS = ['', '/docs', '/documentation'];
export function isApiStaticExportBasePath(basePath) {
    return API_STATIC_EXPORT_BASE_PATHS.includes(basePath);
}
